#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

#define GPIOD_BASE_ADDR			0x40020C00UL
#define GPIOD_ODR_REG_OFFSET	0x14UL
#define GPIOD_MODER_REG_OFFSET	0x00UL
#define GPIOD_ODR_BASE_ADDR		(GPIOD_BASE_ADDR+GPIOD_ODR_REG_OFFSET)
#define GPIOD_MODER_BASE_ADDR	(GPIOD_BASE_ADDR+GPIOD_MODER_REG_OFFSET)

#define RCC_BASE_ADDR			0x40023800UL
#define RCC_AHB1ENR_REG_OFFSET	0x30UL
#define RCC_AHB1ENR_BASE_ADDR	(RCC_BASE_ADDR+RCC_AHB1ENR_REG_OFFSET)

//This code runs on STM32F407G Microcontroller, in STM32CubeIDE environment.
//GPIOD is connected to four LEDs. This program turn each of them on in turns.
int main(void)
{
	//For any 0<=i<=3 LED i is on i.f.f. GPIOD_ODR<12+i> == 1 and GPIOD_MODER<12+i> == 0b01
	uint32_t *pGpiodOdrReg = (uint32_t*) GPIOD_ODR_BASE_ADDR;
	uint32_t *pGpiodModerReg = (uint32_t*) GPIOD_MODER_BASE_ADDR;
	uint32_t *pRccAhb1enrReg = (uint32_t *) RCC_AHB1ENR_BASE_ADDR;
	uint32_t odrMask = 1 << 12;
	uint32_t moderMaskReset = 3 << (2*12);
	uint32_t moderMaskOutput = 1 << (2*12);

	*pRccAhb1enrReg |= 1 << 3;

	for(int i = 12; i <= 15; i++) {
		//GPIOD_MODER<12+i> <- 0b00
		*pGpiodModerReg &= ~moderMaskReset;
		//GPIOD_MODER<12+i> <- 0b01
		*pGpiodModerReg |= moderMaskOutput;
		//GPIO_ODR<12+i> <- 1 (LED i-12 is on)
		*pGpiodOdrReg |= odrMask;
		//GPIOD_MODER<12+i> <- 0b00 (LED i-12 is off)
		*pGpiodModerReg &= ~moderMaskReset;
		// Advance to the next LED
		odrMask = odrMask << 1;
		moderMaskReset = moderMaskReset << 2;
		moderMaskOutput = moderMaskOutput << 2;
	}


    /* Loop forever */
	for(;;);
}
